pub fn new(program: &str, args: &[&str]) -> Cmd {
    let mut argv = vec![OsString::from(program)];
    argv.extend(args.iter().map(OsString::from));
    Cmd {
        program: PathBuf::from(program),
        argv,
        env: std::env::vars_os().collect(),
        cwd: std::env::current_dir().unwrap(),
        stdin: false,
        merge: true,
        grace_ms: 300,
        verbatim: None,
    }
}

/// This test binary in a child role (`role.rs`).
pub fn role(spec: &str) -> Cmd {
    let exe = std::env::current_exe().unwrap();
    let mut c = Cmd::new(
        exe.to_str().unwrap(),
        &["--exact", "role", "--nocapture", "--test-threads=1", "-q"],
    );
    c.env.retain(|(k, _)| k != super::role::VAR);
    c.env.push((super::role::VAR.into(), spec.into()));
    c

/// The same command through `std::process` (the in-host control), stdout piped.
pub fn std(&self) -> Command {
    let mut c = Command::new(&self.program);
    c.args(&self.argv[1..])
        .env_clear()
        .envs(self.env.iter().cloned())
        .current_dir(&self.cwd);
    c.stdin(Stdio::null()).stdout(Stdio::piped());
    c
}

pub fn spawn_msg(&self, req: u64) -> Spawn {
    let b = |s: &std::ffi::OsStr| s.as_bytes().to_vec();
    Spawn {
        req,
        program: b(self.program.as_os_str()),
        argv: self.argv.iter().map(|a| b(a)).collect(),
        env: self.env.iter().map(|(k, v)| (b(k), b(v))).collect(),
        cwd: b(self.cwd.as_os_str()),
        pty: None,
        stdin: if self.stdin { Slot::Pipe } else { Slot::Null },
        stderr: if self.merge { Slot::Merge } else { Slot::Pipe },
        grace_ms: self.grace_ms,
        handles: [0; 3],
        verbatim: self.verbatim.clone(),
    }

/// Bound for every single observation; reaching it fails the test.
pub const T: Duration = Duration::from_secs(10);

/// The supervisor under test: `HUGR_OMNI_SUPERVISOR` (e.g. the static musl build), else this package's binary.
pub fn sup_path() -> PathBuf {
    std::env::var_os("HUGR_OMNI_SUPERVISOR")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(env!("CARGO_BIN_EXE_hugr-omni-supervisor")))
}

/// Lines of a pipe, read by a thread.
pub struct Lines(mpsc::Receiver<String>);

impl Lines {
    pub fn new(r: impl Read + Send + 'static) -> Lines {
        let (tx, rx) = mpsc::channel();
        std::thread::spawn(move || {
            for line in BufReader::new(r).lines() {
                let Ok(line) = line else { break };
                if tx.send(line).is_err() {
                    break;
                }
            }
        });
        Lines(rx)
    }

    /// The next line; `None` at end of file. Fails the test after `T`.
    pub fn next(&self) -> Option<String> {
        match self.0.recv_timeout(T) {
            Ok(l) => Some(l),
            Err(mpsc::RecvTimeoutError::Disconnected) => None,
            Err(mpsc::RecvTimeoutError::Timeout) => panic!("no output line within {T:?}"),

pub fn start_with(setup: impl FnOnce(&mut Command)) -> Host {
    let (ours, theirs) = UnixStream::pair().unwrap();
    let mut cmd = Command::new(sup_path());
    cmd.arg("--host-pid").arg(std::process::id().to_string());
    cmd.stdin(Stdio::from(OwnedFd::from(theirs))).process_group(0);
    setup(&mut cmd);
    let sup = cmd.spawn().unwrap();
    let mut h = Host {
        sup,
        sock: ours,
        rbuf: Vec::new(),
        info: 0,
        next: 1,
        exits: HashMap::new(),
        stash: VecDeque::new(),
    };
    match h.recv() {
        Some(Msg::Ready { version, pid, info }) => {
            assert_eq!((version, pid), (omni_proto::VERSION, h.sup.id()));
            h.info = info;
        }
        other => panic!("expected Ready, got {other:?}"),
    }

/// The reply to `req`. `Exited` on the way is recorded; other replies wait in a stash.
pub fn reply(&mut self, req: u64) -> Msg {
    if let Some(i) = self.stash.iter().position(|m| req_of(m) == Some(req)) {
        return self.stash.remove(i).unwrap();
    }
    loop {
        match self.recv().expect("the supervisor closed the channel") {
            Msg::Exited { id, exit } => assert!(self.exits.insert(id, exit).is_none(), "second Exited for {id}"),
            m if req_of(&m) == Some(req) => return m,
            m => self.stash.push_back(m),
        }
    }

pub fn try_spawn(&mut self, cmd: &Cmd) -> Result<Tree, (FailCode, i32, String)> {
    let (out_r, out_w) = std::io::pipe().unwrap();
    let (in_r, in_w) = if cmd.stdin {
        Some(std::io::pipe().unwrap())
    } else {
        None
    }
    .unzip();
    let (err_r, err_w) = if cmd.merge {
        None
    } else {
        Some(std::io::pipe().unwrap())
    }
    .unzip();
    let mut fds: Vec<RawFd> = in_r.iter().map(AsRawFd::as_raw_fd).collect();
    fds.push(out_w.as_raw_fd());
    fds.extend(err_w.iter().map(AsRawFd::as_raw_fd));
    let req = self.req();
    self.send(&Msg::Spawn(cmd.spawn_msg(req)), &fds);
    drop((in_r, out_w, err_w)); // the supervisor and the child hold their own copies
    match self.reply(req) {
        Msg::Spawned { id, pid, pty_ends, .. } => {
            assert_eq!(pty_ends, [0, 0]);
            Ok(Tree {
                id,
                pid: pid as i32,
                out: Lines::new(out_r),
                err: err_r.map(Lines::new),
                stdin: in_w,
            })
        }
        Msg::SpawnFailed { code, errno, msg, .. } => Err((code, errno, msg)),
        other => panic!("expected Spawned, got {other:?}"),
    }

    /// Closes the channel (host death for the supervisor) and returns the supervisor's exit status.
    pub fn close(mut self) -> ExitStatus {
        // Shut down, not just drop: `self` still owns the socket until the end of this function.
        self.sock.shutdown(std::net::Shutdown::Both).unwrap();
        wait_child(&mut self.sup, T).expect("the supervisor did not exit after host death")
    }
}

impl Drop for Host {
    fn drop(&mut self) {
        let _ = self.sock.shutdown(std::net::Shutdown::Both);
        if wait_child(&mut self.sup, T).is_none() {
            let _ = self.sup.kill();
            let _ = self.sup.wait();
        }
    }
}

/// Bounded `wait` on a child of this process.
pub fn wait_child(c: &mut Child, within: Duration) -> Option<ExitStatus> {
    let end = Instant::now() + within;
    loop {
        if let Some(st) = c.try_wait().unwrap() {
            return Some(st);
        }
        if Instant::now() >= end {
            return None;
        }
        std::thread::sleep(Duration::from_millis(5));
    }

pub fn run(mode: &str) {
    let mut host = match mode {
        #[cfg(target_os = "linux")]
        "held-nopidfd" => Host::start_with(super::os::without_pidfd),
        _ => Host::start(),
    };
    let grace = if mode == "idle" { 1000 } else { 300 };
    let tree = host.spawn(&Cmd::role("tree hang resist+group resist").grace(grace));
    let leaves = field(&tree.out.take("UP ", 2), 1);
    say(&format!(
        "TREE {} {} {} {}",
        tree.pid,
        leaves[0],
        leaves[1],
        host.sup.id()
    ));
    say(&format!("INFO {}", host.info));

"midspawn" => {
    // A complete Spawn; once its child runs, die before reading `Spawned`.
    let (out_r, out_w) = std::io::pipe().unwrap();
    let req = host.req();
    host.send(
        &Msg::Spawn(Cmd::role("leaf plain").spawn_msg(req)),
        &[out_w.as_raw_fd()],
    );
    drop(out_w);
    let up = Lines::new(out_r).take("UP ", 1);
    say(&format!("INFLIGHT {}", field(&up, 1)[0]));
    die()
}
"partial" => {
    // Half a Spawn frame, its descriptor riding on the first byte; then die.
    let (_out_r, out_w) = std::io::pipe().unwrap();
    let mut bytes = Vec::new();
    encode(&Msg::Spawn(Cmd::role("leaf plain").spawn_msg(host.req())), &mut bytes).unwrap();
    let half = &bytes[..bytes.len() / 2];
    assert_eq!(send_with_fds(&host.sock, half, &[out_w.as_raw_fd()]), half.len());
    say("PARTIAL");
    die()
}
"held" | "held-nopidfd" => {
    // A copy of the channel without close-on-exec, kept open by an unrelated child: no EOF at death.
    // SAFETY: dup of our own socket; the copy is closed below, after the holder inherited it.
    let copy = unsafe { libc::dup(host.sock.as_raw_fd()) };
    assert!(copy >= 0);
    // Never waited for on purpose: it outlives this host, and the test kills it.
    #[allow(clippy::zombie_processes)]
    let holder = command("leaf plain").stdout(Stdio::null()).spawn().unwrap();
    // SAFETY: closing the copy we just made.
    unsafe { libc::close(copy) };
    say(&format!("HOLDER {}", holder.id()));
    say("WAIT");
    hang()

/// How long the `idle` host leaves its supervisor without any event.
pub const IDLE: std::time::Duration = std::time::Duration::from_millis(1500);

fn die() -> ! {
    // SAFETY: plain integer argument; SIGKILL cannot be caught.
    unsafe { libc::raise(libc::SIGKILL) };
    hang()

//! Shared helpers of the Unix supervisor suite (SUP-U): a test host, the OS oracle and the child roles.
// Each test binary uses a different part of these helpers; the rest would warn as dead code there.
#![allow(dead_code)]

pub mod cmd;
pub mod host;
pub mod host_role;
pub mod os;
pub mod role;

/// The process exists (alive or a zombie). Permission errors count as existing.
pub fn exists(pid: i32) -> bool {
    // SAFETY: signal 0 only checks for existence.
    unsafe { libc::kill(pid, 0) == 0 || *errno() == libc::EPERM }
}

/// The process exists and is not a zombie. A zombie thread-group leader whose other threads still run is
/// alive: every task of `/proc/<pid>/task` is asked. An observation that cannot be made fails the test.
#[cfg(target_os = "linux")]
pub fn alive(pid: i32) -> bool {
    match state(&format!("/proc/{pid}/stat")) {
        None | Some(b'X') => false,
        Some(b'Z') => {
            let tasks = match std::fs::read_dir(format!("/proc/{pid}/task")) {
                Ok(dir) => dir,
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => return false,
                Err(e) => panic!("cannot list the threads of {pid}: {e}"),
            };
            tasks
                .map(|t| {
                    t.unwrap_or_else(|e| panic!("cannot list the threads of {pid}: {e}"))
                        .file_name()
                })
                .filter_map(|tid| state(&format!("/proc/{pid}/task/{}/stat", tid.to_string_lossy())))
                .any(|s| !matches!(s, b'Z' | b'X'))
        }
        Some(_) => true,
    }
}

/// The state letter of a `stat` file; `None` when the process or thread is gone.
#[cfg(target_os = "linux")]
fn state(path: &str) -> Option<u8> {
    match std::fs::read_to_string(path) {
        Ok(s) => Some(
            *s.rsplit_once(')')
                .unwrap_or_else(|| panic!("unparsable {path}"))
                .1
                .trim_start()
                .as_bytes()
                .first()
                .unwrap(),
        ),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound || e.raw_os_error() == Some(libc::ESRCH) => None,
        Err(e) => panic!("cannot read {path}: {e}"),
    }

/// The process exists and is not a zombie. A process being torn down (after SIGKILL, before it is a
/// zombie) counts as alive: `getsid` and `proc_pidinfo` already fail for it, so only the kernel's process
/// table (`sysctl(KERN_PROC_PID)`) can tell (Codex/lead r4: an exiting process is not gone).
#[cfg(target_os = "macos")]
pub fn alive(pid: i32) -> bool {
    // kinfo_proc (<sys/sysctl.h>, 648 bytes on LP64): kp_proc.p_stat at 36, kp_proc.p_pid at 40.
    let mut mib = [libc::CTL_KERN, libc::KERN_PROC, libc::KERN_PROC_PID, pid];
    let mut buf = [0u8; 648];
    let mut len: libc::size_t = buf.len();
    // SAFETY: `buf` has `len` writable bytes.
    let r = unsafe {
        libc::sysctl(
            mib.as_mut_ptr(),
            4,
            buf.as_mut_ptr().cast(),
            &raw mut len,
            std::ptr::null_mut(),
            0,
        )
    };
    assert_eq!(r, 0, "sysctl(KERN_PROC_PID, {pid}) failed");
    len == buf.len() && i32::from_ne_bytes(buf[40..44].try_into().unwrap()) == pid && u32::from(buf[36]) != libc::SZOMB
}

/// Open descriptor numbers of another process of ours.
#[cfg(target_os = "linux")]
pub fn fds_of(pid: u32) -> Vec<i32> {
    let mut v: Vec<i32> = std::fs::read_dir(format!("/proc/{pid}/fd"))
        .unwrap()
        .filter_map(|e| e.ok()?.file_name().to_str()?.parse().ok())
        .collect();
    v.sort_unstable();
    v
}

/// Open descriptor numbers of another process of ours.
#[cfg(target_os = "macos")]
pub fn fds_of(pid: u32) -> Vec<i32> {
    // SAFETY: plain old data, written by proc_pidinfo up to the given size.
    let mut buf: Vec<libc::proc_fdinfo> = vec![unsafe { std::mem::zeroed() }; 4096];
    let bytes = (buf.len() * std::mem::size_of::<libc::proc_fdinfo>()) as libc::c_int;
    // SAFETY: `buf` has `bytes` writable bytes.
    let n = unsafe { libc::proc_pidinfo(pid as i32, libc::PROC_PIDLISTFDS, 0, buf.as_mut_ptr().cast(), bytes) };
    assert!(n > 0, "proc_pidinfo(PROC_PIDLISTFDS) of {pid} failed");
    let count = n as usize / std::mem::size_of::<libc::proc_fdinfo>();
    let mut v: Vec<i32> = buf.iter().take(count).map(|f| f.proc_fd).collect();
    v.sort_unstable();
    v

/// A hostile parent for the next exec (runs between fork and exec): leaks fd 99 without close-on-exec,
/// ignores SIGINT/SIGHUP/SIGTERM/SIGUSR1 and SIGCHLD (auto-reap!), and blocks SIGUSR2.
pub fn hostile(cmd: &mut std::process::Command) {
    use std::os::unix::process::CommandExt;
    let hook = || {
        // SAFETY: async-signal-safe calls on locals, in the child before exec.
        unsafe {
            if libc::dup2(2, 99) != 99 {
                return Err(std::io::Error::last_os_error());
            }
            for sig in [libc::SIGINT, libc::SIGHUP, libc::SIGTERM, libc::SIGUSR1, libc::SIGCHLD] {
                libc::signal(sig, libc::SIG_IGN);
            }
            let mut set: libc::sigset_t = std::mem::zeroed();
            libc::sigemptyset(&raw mut set);
            libc::sigaddset(&raw mut set, libc::SIGUSR2);
            libc::sigprocmask(libc::SIG_BLOCK, &raw const set, std::ptr::null_mut());
        }
        Ok(())
    };
    // SAFETY: the hook only makes async-signal-safe calls.
    unsafe { cmd.pre_exec(hook) };
}

/// Simulates a kernel without pidfd for the next exec: `pidfd_open` and `pidfd_send_signal` fail with
/// ENOSYS, exactly as on Linux < 5.3. The product binary has no switch for it.
#[cfg(target_os = "linux")]
pub fn without_pidfd(cmd: &mut std::process::Command) {
    deny(cmd, &[libc::SYS_pidfd_open, libc::SYS_pidfd_send_signal]);
}

