/// A seccomp filter for the next exec that makes the given syscalls fail with ENOSYS.
#[cfg(target_os = "linux")]
fn deny(cmd: &mut std::process::Command, syscalls: &[libc::c_long]) {
    use std::os::unix::process::CommandExt;
    let stmt = |code: u32, k: u32| libc::sock_filter {
        code: code as u16,
        jt: 0,
        jf: 0,
        k,
    };
    let n = syscalls.len();
    let mut filter = vec![stmt(libc::BPF_LD | libc::BPF_W | libc::BPF_ABS, 0)]; // the syscall number
    for (i, &nr) in syscalls.iter().enumerate() {
        let to_deny = (n - i) as u8; // skip the remaining checks and the ALLOW
        filter.push(libc::sock_filter {
            code: (libc::BPF_JMP | libc::BPF_JEQ | libc::BPF_K) as u16,
            jt: to_deny,
            jf: 0,
            k: nr as u32,
        });
    }
    filter.push(stmt(libc::BPF_RET | libc::BPF_K, libc::SECCOMP_RET_ALLOW));
    filter.push(stmt(
        libc::BPF_RET | libc::BPF_K,
        libc::SECCOMP_RET_ERRNO | libc::ENOSYS as u32,
    ));
    // Built before the fork: the hook below only reads it.
    let hook = move || {
        let prog = libc::sock_fprog {
            len: filter.len() as u16,
            filter: filter.as_ptr().cast_mut(),
        };
        // SAFETY: prctl with plain arguments and a pointer to a live filter program; no allocation.
        unsafe {
            if libc::prctl(libc::PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) != 0
                || libc::prctl(libc::PR_SET_SECCOMP, libc::SECCOMP_MODE_FILTER, &raw const prog) != 0
            {
                return Err(std::io::Error::last_os_error());
            }
        }
        Ok(())
    };
    // SAFETY: the hook only makes async-signal-safe calls.
    unsafe { cmd.pre_exec(hook) };

/// The variable that selects a role.
pub const VAR: &str = "OMNI_SUP_ROLE";
const LIFETIME: Duration = Duration::from_secs(60);
const LONG_LIFETIME: Duration = Duration::from_secs(600);

/// Runs the role named by `OMNI_SUP_ROLE` and exits; returns at once in a normal test run.
pub fn main() {
    let Ok(spec) = std::env::var(VAR) else { return };
    let snapshot = Snapshot::take(); // before anything opens a descriptor
    let lifetime = if spec.contains("long") { LONG_LIFETIME } else { LIFETIME };
    std::thread::spawn(move || {
        std::thread::sleep(lifetime);
        std::process::exit(70);
    });
    let words: Vec<&str> = spec.split(' ').collect();
    match words.as_slice() {
        ["info"] => snapshot.print(),
        ["out"] => {
            say("OUT");
            std::io::stderr().write_all(b"ERR\n").unwrap();
        }
        ["exit", code] => std::process::exit(code.parse().unwrap()),
        ["raise", sig] => {
            // SAFETY: plain integer argument; the signal has its default disposition.
            unsafe { libc::raise(sig.parse().unwrap()) };
        }
        ["leaf", flags] => leaf(flags),
        ["tree", then, leaves @ ..] => tree(then, leaves),
        ["host", mode] => super::host_role::run(mode),
        ["cycle", lo, hi] => cycle(lo.parse().unwrap(), hi.parse().unwrap()),
        _ => std::process::exit(99),
    }
    std::process::exit(0);

fn leaf(flags: &str) {
    for flag in flags.split('+') {
        match flag {
            "resist" => ignore_term(),
            // SAFETY: the handler only makes async-signal-safe calls.
            "report" => unsafe {
                libc::signal(
                    libc::SIGTERM,
                    on_term as extern "C" fn(libc::c_int) as libc::sighandler_t,
                );
            },
            // SAFETY: plain integer arguments.
            "group" => assert_eq!(unsafe { libc::setpgid(0, 0) }, 0),
            "plain" | "long" => {}
            "heavy" => heavy(),
            #[cfg(target_os = "linux")]
            "zleader" => zleader(),
            other => panic!("unknown leaf flag {other}"),
        }
    }
    say(&format!("UP {}", ids()));
    hang()

/// Ends the main thread only (the raw `exit` syscall, as `pthread_exit` does, from a SIGUSR1 handler sent to
/// it with `tgkill`) while a thread keeps the process running; never returns.
#[cfg(target_os = "linux")]
fn zleader() -> ! {
    extern "C" fn end_this_thread(_: libc::c_int) {
        // SAFETY: the raw exit syscall ends only the calling thread; async-signal-safe.
        unsafe { libc::syscall(libc::SYS_exit, 0) };
    }
    std::thread::spawn(|| {
        let me = std::process::id();
        let zombie = || {
            let s = std::fs::read_to_string(format!("/proc/{me}/stat")).unwrap();
            s.rsplit_once(')')
                .is_some_and(|(_, rest)| rest.trim_start().starts_with('Z'))
        };
        while !zombie() {
            std::thread::sleep(Duration::from_millis(1));
        }
        say(&format!("ZLEADER {}", ids()));
        hang()
    });
    // SAFETY: installs a handler that only calls an async-signal-safe syscall, then signals the main thread.
    unsafe {
        libc::signal(
            libc::SIGUSR1,
            end_this_thread as extern "C" fn(libc::c_int) as libc::sighandler_t,
        );
        let pid = libc::getpid();
        libc::syscall(libc::SYS_tgkill, pid, pid, libc::SIGUSR1);
    }
    hang()
}

/// Makes the process slow to tear down: memory to unmap and threads to end after SIGKILL.
fn heavy() {
    let heap: Vec<Vec<u8>> = (0..64).map(|_| vec![1u8; 4 << 20]).collect();
    std::mem::forget(heap);
    for _ in 0..64 {
        std::thread::spawn(|| std::thread::sleep(Duration::from_secs(3600)));
    }

fn tree(then: &str, leaves: &[&str]) {
    for flags in leaves {
        // Never waited for on purpose: the leaves outlive this root (they are the tree under test).
        #[allow(clippy::zombie_processes)]
        command(&format!("leaf {flags}")).spawn().unwrap();
    }
    say(&format!("ROOT {}", ids()));
    match then {
        "hang" => hang(),
        "exit" => {}
        "stdin" => _ = std::io::copy(&mut std::io::stdin(), &mut std::io::sink()),
        other => panic!("unknown tree end {other}"),
    }
}

fn cycle(lo: i32, hi: i32) {
    loop {
        // SAFETY: the child only calls _exit.
        let pid = unsafe { libc::fork() };
        if pid == 0 {
            // SAFETY: async-signal-safe exit of the forked child.
            unsafe { libc::_exit(0) };
        }
        let mut st = 0;
        // SAFETY: reaping our own child.
        unsafe { libc::waitpid(pid, &raw mut st, 0) };
        if (lo..hi).contains(&pid) {
            return;
        }
    }

impl Snapshot {
    fn take() -> Snapshot {
        // SAFETY: queries only: F_GETFD, sigaction with no new action, sigprocmask with no new set.
        unsafe {
            let fds = (0..1024).filter(|&fd| libc::fcntl(fd, libc::F_GETFD) != -1).collect();
            let mut ignored = Vec::new();
            let mut blocked = Vec::new();
            let mut cur: libc::sigset_t = std::mem::zeroed();
            libc::sigprocmask(libc::SIG_BLOCK, std::ptr::null(), &raw mut cur);
            for sig in 1..32 {
                let mut old: libc::sigaction = std::mem::zeroed();
                if libc::sigaction(sig, std::ptr::null(), &raw mut old) == 0 && old.sa_sigaction == libc::SIG_IGN {
                    ignored.push(sig);
                }
                if libc::sigismember(&raw const cur, sig) == 1 {
                    blocked.push(sig);
                }
            }
            Snapshot { fds, ignored, blocked }

/// Runs `host <mode>`, kills it `by`, checks it died as `want`, then that zero tree processes survive and
/// the supervisor exited; returns the host's `Ready.info` and the time from its death to zero survivors.
fn host_dies(mode: &str, by: By, want: Death) -> (u32, Duration) {
    let mut c = command(&format!("host {mode}"));
    c.process_group(0).stdout(Stdio::piped());
    let mut host = c.spawn().unwrap();
    let out = Lines::new(host.stdout.take().unwrap());
    let line = out.take("TREE ", 1).remove(0);
    let nums: Vec<i32> = line.split(' ').skip(1).map(|s| s.parse().unwrap()).collect();
    let (mut tree, sup) = (nums[..3].to_vec(), nums[3]);
    let info = field(&out.take("INFO ", 1), 1)[0] as u32;
    let mut holder = None;
    match mode {
        "midspawn" => tree.extend(field(&out.take("INFLIGHT ", 1), 1)),
        "partial" => _ = out.take("PARTIAL", 1),
        "held" | "held-nopidfd" => {
            holder = Some(field(&out.take("HOLDER ", 1), 1)[0]);
            out.take("WAIT", 1);
        }
        "signal" => _ = out.take("WAIT", 1),
        _ => {}
    }
    let host_pid = host.id() as i32;
    match by {
        By::Itself => {}
        By::Test(sig) => kill(host_pid, sig),
        By::TestToGroup(sig) => killpg(host_pid, sig),
    }
    let status = wait_child(&mut host, T).expect("the host did not die");
    match want {
        Death::Code(code) => assert_eq!(status.code(), Some(code), "{mode}: {status:?}"),
        Death::Signal(sig) => assert_eq!(signal_of(status), Some(sig), "{mode}: {status:?}"),
    }
    let dead = Instant::now();
    let clean = wait_until(Duration::from_secs(3), || {
        tree.iter().all(|&p| !alive(p)) && !alive(sup)
    });
    let survivors: Vec<i32> = tree.iter().copied().filter(|&p| alive(p)).collect();
    if let Some(h) = holder {
        kill(h, libc::SIGKILL);
    }
    assert!(
        clean,
        "{mode}: survivors {survivors:?}, supervisor alive: {} ({:?} after death)",
        alive(sup),
        dead.elapsed()
    );
    (info, dead.elapsed())

